PROCEDURE @@proc@@ (p_name IN VARCHAR2, p_limit IN NUMBER) IS
BEGIN
    EXECUTE IMMEDIATE 'UPDATE @@tab@@ ' || CHR(10) || -- @expect
                      '   SET @@col@@ = ' || p_limit || CHR(10) ||
                      ' WHERE @@col2@@ = ''' || p_name || '''';
    IF SQL%ROWCOUNT = 0 THEN
        RAISE_APPLICATION_ERROR(-20001, 'nothing updated');
    END IF;
END @@proc@@;

PROCEDURE @@proc@@ (p_cols IN SYS.ODCIVARCHAR2LIST) IS
    l_sql VARCHAR2(4000) := 'DELETE FROM @@tab@@ WHERE ROWNUM > 0';
BEGIN
    FOR i IN 1 .. p_cols.COUNT LOOP
        l_sql := l_sql || ' AND ' || p_cols(i) || ' IS NULL';
    END LOOP;
    EXECUTE IMMEDIATE l_sql; -- @expect
    DBMS_OUTPUT.PUT_LINE(SQL%ROWCOUNT);
END @@proc@@;

FUNCTION @@proc@@ (p_table IN VARCHAR2, p_min IN NUMBER) RETURN NUMBER IS
    l_cnt NUMBER;
BEGIN
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM ' || p_table -- @expect
                      || ' WHERE @@col@@ > :min_val'
        INTO l_cnt
        USING p_min;
    RETURN l_cnt;
END @@proc@@;

PROCEDURE @@proc@@ (p_filter IN VARCHAR2, p_rc OUT SYS_REFCURSOR) IS
    l_sql VARCHAR2(2000);
BEGIN
    IF p_filter IS NULL THEN
        RAISE_APPLICATION_ERROR(-20002, 'filter required');
    END IF;
    l_sql := 'SELECT @@col@@, @@col2@@ FROM @@tab@@ '
          || 'WHERE @@col@@ LIKE ''' || p_filter || '%''';
    OPEN p_rc FOR l_sql; -- @expect
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER) IS
    l_days PLS_INTEGER := 30;
BEGIN
    EXECUTE IMMEDIATE 'DELETE FROM @@tab@@ WHERE @@col@@ < SYSDATE - ' -- @expect
                      || TO_CHAR(l_days)
                      || ' AND id = '
                      || TO_CHAR(p_id);
    DBMS_OUTPUT.PUT_LINE(SQL%ROWCOUNT || ' rows removed');
END @@proc@@;

