FUNCTION @@proc@@ (p_owner IN VARCHAR2, p_table IN VARCHAR2) RETURN NUMBER IS
    l_cnt NUMBER;
BEGIN
    EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM '
                      || sys.dbms_assert.schema_name(p_owner)
                      || '.'
                      || dbms_assert.simple_sql_name(p_table)
        INTO l_cnt;
    RETURN l_cnt;
END @@proc@@;

PROCEDURE @@proc@@ (p_rc OUT SYS_REFCURSOR) IS
    l_sql VARCHAR2(500);
BEGIN
    EXECUTE IMMEDIATE q'[
        UPDATE @@tab@@
           SET @@col@@ = 'ACTIVE'
         WHERE @@col2@@ IS NULL
    ]';
    l_sql := q'[SELECT @@col@@ FROM @@tab@@ WHERE @@col@@ = 'ACTIVE']';
    OPEN p_rc FOR l_sql;
END @@proc@@;

PROCEDURE @@proc@@ (p_id IN NUMBER, p_val IN NUMBER, p_new OUT NUMBER) IS
    l_max NUMBER;
BEGIN
    EXECUTE IMMEDIATE 'UPDATE @@tab@@ SET @@col@@ = :b1 WHERE id = :b2 RETURNING @@col2@@'
        USING p_val, p_id
        RETURNING INTO p_new;

    EXECUTE IMMEDIATE 'SELECT MAX(@@col2@@) FROM @@tab@@ WHERE id = :b1'
        INTO l_max
        USING p_id;
    DBMS_OUTPUT.PUT_LINE(l_max);
END @@proc@@;

PROCEDURE @@proc@@ (p_mode IN VARCHAR2) IS
    l_sql VARCHAR2(200);
BEGIN
    IF p_mode = 'FULL' THEN
        l_sql := 'TRUNCATE TABLE @@tab@@';
    ELSIF p_mode = 'PARTIAL' THEN
        l_sql := 'DELETE FROM @@tab@@ WHERE @@col@@ < SYSDATE - 7';
    ELSE
        l_sql := 'DELETE FROM @@tab@@ WHERE 1 = 0';
    END IF;
    EXECUTE IMMEDIATE l_sql;
END @@proc@@;

PROCEDURE @@proc@@ IS
BEGIN
    EXECUTE IMMEDIATE 'CREATE INDEX @@tab@@_ix ON @@tab@@ (@@col@@, @@col2@@) '
                      || 'TABLESPACE users PARALLEL 4';
EXCEPTION
    WHEN OTHERS THEN
        IF SQLCODE != -955 THEN
            RAISE;
        END IF;
END @@proc@@;
